import{_ as l,a0 as p,w as r,s as o,ao as d,I as n,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"删除 Git 远程分支的本地引用 | LCTT x X-CMD","titleTemplate":false,"description":"删除 Git 远程分支的本地引用 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"删除 Git 远程分支的本地引用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"删除 Git 远程分支的本地引用 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220805 Delete the local reference to a remote branch in Git","title":"删除 Git 远程分支的本地引用","tag":"202208","desc":""},"relativePath":"202208/20220805 Delete the local reference to a remote branch in Git.md","filePath":"[post].md"}'),g={name:"202208/20220805 Delete the local reference to a remote branch in Git.md"};function h(c,e,u,b,k,m){const s=p("Link");return r(),o("div",null,[e[15]||(e[15]=d(`<h1 id="删除-git-远程分支的本地引用" tabindex="-1">删除 Git 远程分支的本地引用 <a class="header-anchor" href="#删除-git-远程分支的本地引用" aria-label="Permalink to “删除 Git 远程分支的本地引用”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/11/150612dv5diwgve5k2cobk.jpg" alt=""></p><blockquote><p>遵循几个简单的步骤来保持 Git 仓库的整洁</p></blockquote><p>在合并一个 GibLab 的合并请求（MR）或 GitHub 的拉取请求（PR）后，你通常需要从远程仓库中删掉这个主题分支来保持仓库的整洁。然而，这只会删掉远程仓库的主题分支。本地 Git 仓库也会从例行清理中收益。</p><p>要同步本地仓库和远程仓库的信息，可以执行 <code>git prune</code> 命令来删除本地仓库中远程分支的本地引用。</p><p>按照以下三个简单的步骤：</p><p>1、检出仓库中的核心分支（比如 <code>main</code> 或者 <code>master</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout &lt;central_branch_name&gt;</span></span></code></pre></div><p>2、列出所有远程和本地分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git branch -a</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>4.10.z</span></span>
<span class="line"><span>* master</span></span>
<span class="line"><span>  remotes/mydata/4.9-stage</span></span>
<span class="line"><span>  remotes/mydata/4.9.z</span></span>
<span class="line"><span>  remotes/mydata/test-branch</span></span></code></pre></div><p>在这个例子中，<code>test-branch</code> 是从远程仓库中删除的主题分支的名字。</p><p>3、删除远程分支的本地引用：</p><p>首先，列出所有可以从本地仓库中删除的分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote prune origin --dry-run</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pruning origin</span></span>
<span class="line"><span>URL: git@example.com:myorg/mydata-4.10.git</span></span>
<span class="line"><span>* [would prune] origin/test-branch</span></span></code></pre></div><p>然后，删除远程分支的本地引用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote prune origin</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pruning origin</span></span>
<span class="line"><span>URL: git@example.com:myorg/mydata-4.10.git</span></span>
<span class="line"><span>* [pruned] origin/test-branch</span></span></code></pre></div><p>就是这样！</p><h3 id="维护-git-仓库" tabindex="-1">维护 Git 仓库 <a class="header-anchor" href="#维护-git-仓库" aria-label="Permalink to “维护 Git 仓库”">​</a></h3><p>保持 Git 仓库的整洁，一开始似乎并不紧急，但是随着仓库规模的增长，删除不必要的数据就变得更为重要。不要让从无用的数据筛选而拖慢你。</p><p>经常删除远程分支的本地引用，是维护一个可用的 Git 仓库是一个好方法。</p><hr>`,27)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),i(s,{href:"https://opensource.com/article/22/8/delete-local-reference-remote-branch-git"},{default:a(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/22/8/delete-local-reference-remote-branch-git",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),i(s,{href:"https://opensource.com/users/agantony"},{default:a(()=>[...e[2]||(e[2]=[t("Agil Antony",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),i(s,{href:"https://github.com/lkxed"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),i(s,{href:"https://github.com/Yufei-Yan"},{default:a(()=>[...e[4]||(e[4]=[t("Yufei-Yan",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const x=l(g,[["render",h]]);export{C as __pageData,x as default};
